#include <SPI.h>
#include <MFRC522.h>
#include <RF24.h>

// --- Pin ta'riflari ---
#define GAS_PIN    34   // MQ-5 AO analog pini
#define POT_PIN    4    // Potensiometr signal pini (Sezgirlik uchun)
#define BUZZER_PIN 16   // Buzzer pini

// RC522 RFID pinlari
#define SS_PIN     5    // RC522 SDA (SS) pini
#define RST_PIN    22   // RC522 RST pini

MFRC522 rfid(SS_PIN, RST_PIN);

void setup() {
  Serial.begin(115200);

  // Pin rejimlari
  pinMode(GAS_PIN, INPUT);
  pinMode(POT_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  // SPI va RC522 modulini ishga tushirish
  SPI.begin();
  rfid.PCD_Init();

  Serial.println("======================================");
  Serial.println("Tizim tayyor: MQ-5 Gaz Sniffer + RC522");
  Serial.println("======================================");
}

void loop() {
  // ----------------------------------------------------
  // 1. MQ-5 VA POTENSIOMETR MANTIQLARI (Gaz detektori)
  // ----------------------------------------------------
  int gasVal = analogRead(GAS_PIN);
  int potVal = analogRead(POT_PIN);

  // Potensiometr orqali chidamlilik (sezgirlik) chegarasini sozlash (300 - 3800)
  int threshold = map(potVal, 0, 4095, 300, 3800);

  // Gaz konsentratsiyasi chegaradan oshsa "Geyger effekti" bilan chiyillaydi
  if (gasVal > threshold) {
    int delayTime = map(gasVal, threshold, 4095, 250, 10);
    if (delayTime < 10) delayTime = 10;

    digitalWrite(BUZZER_PIN, HIGH);
    delay(20);
    digitalWrite(BUZZER_PIN, LOW);
    delay(delayTime);
  } else {
    digitalWrite(BUZZER_PIN, LOW);
  }

  // ----------------------------------------------------
  // 2. RC522 RFID MANTIQLARI (Karta / Brelok o'qish)
  // ----------------------------------------------------
  if (rfid.PICC_IsNewCardPresent() && rfid.PICC_ReadCardSerial()) {
    Serial.print("[RFID] Karta aniqlandi! UID: ");
    String cardUID = "";

    // Karta UID kodini o'qish va formatlash
    for (byte i = 0; i < rfid.uid.size; i++) {
      cardUID += String(rfid.uid.uidByte[i] < 0x10 ? "0" : "");
      cardUID += String(rfid.uid.uidByte[i], HEX);
      if (i < rfid.uid.size - 1) cardUID += ":";
    }
    cardUID.toUpperCase();
    Serial.println(cardUID);

    // Karta to'g'ri o'qilganda qisqa tasdiqlash bipi (100ms)
    digitalWrite(BUZZER_PIN, HIGH);
    delay(100);
    digitalWrite(BUZZER_PIN, LOW);

    // Kartani o'qib bo'lgach aloqani to'xtatish
    rfid.PICC_HaltA();
    rfid.PCD_StopCrypto1();
  }

  delay(10); // Tizim barqarorligi uchun kichik pauza
}
